// TH18 v1.00a st01::MainSub00 (s:1430-1473) with Cir00m/p (s:163-184)
// -> Cir00func (s:135-161) -> async Cir00_at (s:27-57).
// Original coordinates, invulnerable practice shell. The control enemy at (0,0)
// owns the segment and has body collision off; the 20 real enemies keep the source
// hurtbox/body box and the source 90-frame no-body window.
const TIME_LIMIT: int = 1000;      // 120 opening buffer + ~880 local tail estimate
const SOURCE_LIMIT: int = 880;     // no source timer; local estimate of wave + tail
const OPENING_BUFFER: int = 120;
const TH18_BALL2: int = 432;       // etSprite type 5 Ball2, color kept from source

// s:27-57 Cir00_at. etCountD 1/1/1 + 1 layer all ranks; etSpeedD first group is the
// per-rank initial speed (E1.0/N1.3/H3.0/L4.0), second group unused at M=1.
// s:48-54 diffI round count E0/N1/H7/L10; first fire coincides with configuration.
async sub cir_shot() {
    var rank: int = global(GVAR_RANK);
    var w: int = 30 + rand(200);            // s:31/33/37 E/N/LO wait
    if rank == 2 { w = 10 + rand(60); }     // s:35 H wait
    wait(w);
    var speed: fx = 1.0fx;
    if rank == 1 { speed = 1.3fx; }
    if rank == 2 { speed = 3.0fx; }
    if rank == 3 { speed = 4.0fx; }
    var n: int = 0;
    if rank == 1 { n = 1; }
    if rank == 2 { n = 7; }
    if rank == 3 { n = 10; }
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, 4);            // s:42 etSprite(0,5,4)
    sh_aim(0, 1);                           // s:41 etAim(0,0) aimed fan
    sh_ring(0, 0);                          // fan, N=1 = one aimed shot
    sh_count(0, 1, 1);                      // s:43 etCountD(...1...)
    sh_angle(0, 0deg, 0deg);                // s:44 etAngle(0,0,0)
    sh_speed(0, speed, 0fx);                // s:45 etSpeedD
    // s:47 etEx type2 = birth ANIM, omitted by the approved birth-stage policy.
    for i in 0..n {
        sh_fire(0);                         // s:51 etOn(0)
        wait(10);                           // s:52 wait(10)
    }
}

// s:135-161 Cir00func. s:163-184 Cir00m/p differ only in reward drops/ANIM sprite,
// both call this same body. f0 is the inherited parent F0 snapshot; F1 is 300.
async sub cir_main(f0: fx) {
    set_invuln(65535);                      // training shell: enemies stay alive
    set_hurtbox(14fx);                      // s:141 setHurtbox(28,28); ordinary circle width*0.5
    set_hitbox(8fx);                        // s:142 setHitbox(16,16); width*0.5
    set_enemy_flag(ENEMY_NO_BODY, 1);       // s:137 flagSet(3), body-collision bit
    // s:143 moveVel(-pi/2 + RANDF2*3deg, 0.6); one RANDF2 read per spawn.
    var u: int = rand(65536) - 32768;
    var a0: angle = -90deg + ((u * 546 / 32768) as angle);
    move_vel(0, a0, 0.6fx, EASE_LINEAR);
    wait(70);                               // s:144
    move_speed(20, 0fx, EASE_LINEAR);       // s:145 moveSpeedTime(20,0,0)
    spawn cir_shot();                       // s:146 async Cir00_at, next-tick first run
    wait(20);                               // s:147
    set_enemy_flag(ENEMY_NO_BODY, 0);       // s:148 flagClear(3)
    move_vel(0, aim_player(), 0fx, EASE_LINEAR); // s:149 moveVel(ANGLE_PLAYER,0)
    wait(80);                               // s:150
    var a1: angle = atan2(300fx - $self_y, f0 - $self_x); // s:151 to (F0,300)
    move_vel(0, a1, 0fx, EASE_LINEAR);      // s:152
    move_vel(120, a1, 1fx, EASE_LINEAR);    // s:153 moveVelTime(120,0,F2,1.0)
    wait(60);                               // s:154
    loop { wait(1000); }                    // s:156-159
}

